(()=>{const {t,esc,request,image,status,duration}=F;const id=new URLSearchParams(location.search).get('event');let data=null,map=null,resultPage=1,resultPages=1,resultTicket=0;const root=document.querySelector('#raceContent');function countdown(){const el=document.querySelector('#raceCountdown');if(!el||!data)return;if(data.event.timePending){el.textContent=t('ساعة الانطلاق تُعلن لاحقًا');return;}const n=Math.max(0,Math.floor((new Date(data.event.start)-Date.now())/1000));el.textContent=n?Math.floor(n/86400)+' '+t('يوم')+' · '+duration(n%86400):t('انطلق السباق')}function render(){if(!data)return;if(map){map.remove();map=null}const e=I18N.event(data.event),images=e.images?.length?e.images:[{url:null}],rows=data.results||[];root.innerHTML=`<div class="race-hero"><img src="${esc(image(images[0].url,e.type))}" alt="${esc(e.name)}"><div><p class="eyebrow">${esc(e.label)}</p><h1>${esc(e.name)}</h1><p>${esc(e.location)}</p><p>${e.timePending?new Date(e.start).toLocaleDateString(I18N.lang,{timeZone:'Asia/Jerusalem'}):new Date(e.start).toLocaleString(I18N.lang,{timeZone:'Asia/Jerusalem'})}</p><div class="countdown" id="raceCountdown" role="timer"></div><p>${e.feeMinor?new Intl.NumberFormat(I18N.lang,{style:'currency',currency:'ILS'}).format(e.feeMinor/100):t('التسجيل مجاني')}</p><div class="hero-actions"><a class="btn" href="register.html?event=${encodeURIComponent(e.id)}">${t('سجّل مشاركتك')}</a><a class="outline-btn" href="volunteer.html?event=${encodeURIComponent(e.id)}">${t('تطوّع')}</a>${e.registrationProfile!=='student'?`<a class="outline-btn" href="groups.html?event=${encodeURIComponent(e.id)}">${t('تسجيل المجموعات')}</a>`:''}</div></div></div><section class="feature-card"><h2>${t('عن السباق')}</h2><p>${esc(e.description)}</p><div class="seat-grid">${e.distances.map(d=>{const s=e.seats?.[d];return `<article><h3>${esc(I18N.distance(d))}</h3><p>${s?.capacity?`${s.remaining} ${t('مكان متبقّي')} / ${s.capacity}`:t('التسجيل مفتوح')}</p>${s?.remaining===0&&e.waitlistEnabled?`<b>${t('قائمة الانتظار متاحة')}</b>`:''}</article>`}).join('')}</div>${images.length>1?`<div class="race-gallery">${images.map(i=>`<img src="${esc(image(i.url,e.type))}" alt="${esc(e.name)}" loading="lazy">`).join('')}</div>`:''}</section><section class="feature-card"><h2>${t('خريطة المسار')}</h2>${e.route?.length?`<p>${t('نقاط المسار كما أضافها المنظّم.')}</p><div id="routeMap"></div><ul class="route-points">${e.route.filter(p=>p.kind!=='point').map(p=>`<li>${t(p.kind)} · ${esc(p.label)} <a href="https://www.openstreetmap.org/?mlat=${p.lat}&mlon=${p.lng}#map=16/${p.lat}/${p.lng}" target="_blank" rel="noopener">${t('فتح الخريطة')}</a></li>`).join('')}</ul>`:`<p>${t('سيضيف المنظّم المسار لاحقًا.')}</p>`}</section><section class="feature-card"><h2>${t('نتائج السباق')}</h2><div class="form-grid"><label>${t('المسافة')}<select id="resultDistance"><option value="">${t('كل المسافات')}</option>${e.distances.map(d=>`<option>${esc(d)}</option>`).join('')}</select></label><label>${t('الفئة العمرية')}<select id="resultCategory"><option value="">${t('كل الفئات')}</option>${['تحت 18','18–39','40+','غير محددة'].map(c=>`<option value="${c}">${t(c)}</option>`).join('')}</select></label></div><div class="table-wrap"><table><thead><tr><th>${t('الترتيب')}</th><th>${t('رقم المشارك')}</th><th>${t('الاسم')}</th><th>${t('المسافة')}</th><th>${t('الفئة العمرية')}</th><th>${t('الوقت')}</th></tr></thead><tbody id="resultRows"></tbody></table></div><div class="pagination"><button class="outline-btn" id="resultPrevious">${t('السابق')}</button><span id="resultPageStatus"></span><button class="outline-btn" id="resultNext">${t('التالي')}</button></div><p id="resultEmpty" hidden>${t('لا توجد نتائج منشورة بعد.')}</p></section><section class="feature-card"><h2>${t('ألبوم الماراثون')}</h2>${e.album?.length?`<div class="race-gallery">${e.album.map(i=>`<a href="${esc(image(i.url))}" target="_blank" rel="noopener"><img src="${esc(image(i.url))}" alt="${esc(e.name)}" loading="lazy"></a>`).join('')}</div>`:`<p>${t('سيضيف المنظّم صور الفعالية هنا.')}</p>`}</section><section class="feature-card"><h2>${t('رعاة الماراثون')}</h2>${e.sponsors?.length?`<div class="sponsor-grid">${e.sponsors.map(s=>`<article>${s.image?`<img src="${esc(image(s.image.url))}" alt="${esc(s.name)}">`:''}<b>${esc(s.name)}</b>${s.website?`<a href="${esc(s.website)}" target="_blank" rel="noopener">${t('موقع الراعي')}</a>`:''}</article>`).join('')}</div>`:`<p>${t('لم تُضف جهات داعمة لهذا السباق بعد.')}</p>`}</section>`;async function results(){const current=++resultTicket,distance=document.querySelector('#resultDistance').value,category=document.querySelector('#resultCategory').value;let result={items:[],pages:1,total:0};if(data.connected)try{result=await request('/api/results?'+new URLSearchParams({eventId:e.id,page:String(resultPage),distance,category}))}catch(err){status(err.message,true)}if(current!==resultTicket)return;resultPages=result.pages;if(resultPage>resultPages){resultPage=resultPages;return results()}document.querySelector('#resultRows').innerHTML=result.items.map(r=>`<tr><td>${category?r.categoryRank:r.rank}</td><td>${r.bib}</td><td>${esc(r.name)}</td><td>${esc(I18N.distance(r.distance))}</td><td>${t(r.category)}</td><td dir="ltr">${duration(r.seconds)}</td></tr>`).join('');document.querySelector('#resultEmpty').hidden=!!result.items.length;document.querySelector('#resultPageStatus').textContent=t('الصفحة')+' '+resultPage+' / '+resultPages+' · '+result.total;document.querySelector('#resultPrevious').disabled=resultPage<=1;document.querySelector('#resultNext').disabled=resultPage>=resultPages}document.querySelector('#resultDistance').onchange=()=>{resultPage=1;results()};document.querySelector('#resultCategory').onchange=()=>{resultPage=1;results()};document.querySelector('#resultPrevious').onclick=()=>{if(resultPage>1){resultPage--;results()}};document.querySelector('#resultNext').onclick=()=>{if(resultPage<resultPages){resultPage++;results()}};results();countdown();if(e.route?.length&&window.L){map=L.map('routeMap');L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);const points=e.route.map(p=>[p.lat,p.lng]);L.polyline(points,{color:'#326729',weight:5}).addTo(map);e.route.filter(p=>p.kind!=='point').forEach(p=>L.marker([p.lat,p.lng]).addTo(map).bindPopup(esc(t(p.kind)+' · '+p.label)));map.fitBounds(L.latLngBounds(points).pad(.1),{maxZoom:16})}}(async()=>{try{data=await request('/api/race-details?eventId='+encodeURIComponent(id));data.connected=true;render()}catch{const e=RACE_EVENTS.find(e=>e.id===id);if(e){data={event:e,results:[]};render();status('معاينة فقط؛ شغّل الخادم لحفظ التسجيلات وعرضها للأدمن.')}else status('السباق غير موجود',true)}})();setInterval(countdown,1000);window.addEventListener('languagechange',render)})();
